async function refreshResults(state,env,force=false){const pending=(state.markets||[]).filter(m=>m.marked&&m.representativeSelected&&started(m)&&!m.resultFinal),now=Date.now();if(!pending.length)return 0;if(MEM.resultRunning||(!force&&now-MEM.lastResultAttempt<CFG.resultRemoteMinMs))return 0;MEM.resultRunning=true;MEM.lastResultAttempt=now;try{let changed=0,rowsN=0;const errors=[],ts=[...new Set(pending.map(m=>String(m.gmTs)).filter(Boolean))];for(const gmTs of ts){const tasks=await Promise.allSettled([fetchResultInfo(gmTs),fetchGameInfo(gmTs)]),rows=[];for(const z of tasks){if(z.status==="fulfilled")rows.push(...parseResultRows(z.value,gmTs));else errors.push(gmTs+":"+String(z.reason?.message||z.reason));}rowsN+=rows.length;changed+=applyResults(state,rows);}if(changed)markState(state);state.resultAudit={at:nowIso(),ok:errors.length<ts.length*2,rows:rowsN,settledNow:changed,pending:(state.markets||[]).filter(m=>m.marked&&m.representativeSelected&&started(m)&&!m.resultFinal).length,errors};await saveState(state,env);return changed;}catch(e){state.resultAudit={at:nowIso(),ok:false,error:String(e?.message||e)};await saveState(state,env);return 0;}finally{MEM.resultRunning=false;}}
