function publicState(state){const reps=repCards(state),past=(state.settlementLedger||[]).filter(x=>String(x.gmTs)===String(state.gmTs)).sort((a,b)=>String(b.date+b.time).localeCompare(String(a.date+a.time)));return{version:APP_VERSION,build:BUILD_ID,round:state.round,gmTs:state.gmTs,updatedAt:state.updatedAt,policy:{market:"일반승30 / 핸디30 / UO40",grade:"가장추천20 / 추천30 / 일반50",minOdds:POLICY.minOdds},summary:summary(state),sourceAudit:state.sourceAudit,resultAudit:state.resultAudit,marketMixAudit:state.marketMixAudit,gradeAudit:state.gradeAudit,analysisAudit:state.analysisAudit,markingGames:reps.filter(x=>!x.resultFinal),pastGames:past,pollAfterMs:CFG.statePollMs};}
